+        }
+
+        if (email.isEmpty() && phone.isEmpty()) {
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            emailField.setInvalid(true);
+            hasErrors = true;
+        }
+
+        // Message validation
+        String messageText = messageField.getValue();
+        if (messageText.trim().isEmpty()) {
+            messageField.setErrorMessage("Message is required");
+            messageField.setInvalid(true);
+            hasErrors = true;
+        }
+
+        if (messageText.length() > 500) {
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            messageField.setInvalid(true);
+            hasErrors = true;
+        }
+
+        if (hasErrors) {
+            return;
+        }
+
+        // Send message
+        Message message = new Message(
+            nameField.getValue(),
+            email.isEmpty() ? "" : email,
+            phone.isEmpty() ? "" : phone,
+            messageText
+        );
+
+        messageService.addMessage(message);
+
+        // Update grid
+        grid.setItems(messageService.getAllMessages());
+
+        // Show notification
+        Notification.show("Message sent");
+
+        // Clear form
+        clearingForm = true;
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        clearingForm = false;
+
+        // Disable send button
+        sendButton.setEnabled(false);
+        sendDisabledAfterSubmit = true;
+    }
+
+    private boolean isValidEmail(String email) {
+        return email.contains("@") && !email.startsWith("@") && !email.endsWith("@");
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        boolean hasContent = !nameField.getValue().isEmpty()
+                || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty()
+                || !messageField.getValue().isEmpty();
+
+        if (hasContent) {
+            event.postpone();
+
+            Dialog dialog = new Dialog();
+            dialog.setHeaderTitle("Unsaved changes");
+            dialog.add(new NativeLabel("You have unsaved changes. Do you want to discard them?"));
+
+            Button keepButton = new Button("Keep editing", e -> dialog.close());
+            Button discardButton = new Button("Discard", e -> {
+                dialog.close();
+                event.forwardTo(event.getNavigationTarget());
+            });
+
+            dialog.getFooter().add(keepButton, discardButton);
+            dialog.open();
+        }
+    }
+}
